import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';
import {fresh,change,summary,eventsFor,incomeEvents} from '../server/model.mjs';import {calculateScenario} from '../scenario.js';import * as trips from '../trip-planner.js';import * as workflow from '../workflow.js';import {buildPlan,forecastReconciliation} from '../plan-view.js';import {restoreSections} from '../section-state.js';
const date='2026-09-15';
function fixture(){let b=fresh();b=change(b,'account',{name:'Cash',kind:'cash',openingBalance:10000,balanceDate:date},date);b=change(b,'account',{name:'Card',kind:'credit',openingBalance:500,balanceDate:date,limit:1000,payment:100,dueDate:date},date);b=change(b,'settings',{buffer:400,planningConfirmed:true},date);b=change(b,'income',{name:'Paycheck',amount:800,date,frequency:'Biweekly'},date);b=change(b,'bill',{name:'Internet',amount:60,date,frequency:'Monthly'},date);return b;}
test('PC mockup retains all six navigation destinations and four core quick actions',()=>{const a=app(),html=a.run('home()');for(const action of ['need','goal','afford','transaction'])assert.match(html,new RegExp('data-action="'+action+'"'));assert.match(html,/home-columns/);assert.match(html,/home-side/);assert.match(a.run('originalNav()'),/Home[\s\S]*Calendar[\s\S]*Plan[\s\S]*Debt[\s\S]*Goals[\s\S]*Settings/);});
test('expense date rail has accessible dates, a divider and unchanged inline controls',()=>{const a=app(),html=a.run('thisWeekRows()');assert.match(html,/<time class="expense-date" datetime=/);assert.match(html,/timeline-divider/);assert.match(html,/timeline-summary/);assert.match(html,/data-action="skip"/);assert.match(html,/data-action="billPaid"/);});
test('Next 7 Days item types are unbolded and sit closer to their item names',()=>{const a=app(),home=a.run('home()'),css=readFileSync(new URL('../budget-updates.css',import.meta.url),'utf8');assert.match(home,/Expected Income/);assert.match(home,/Internet/);assert.match(css,/\.reference-week \.item-copy>small\s*\{\s*font-weight:\s*400;\s*margin-top:\s*2px/);});
test('desktop debt details expose real balances and preserve payment/edit/delete actions',()=>{const a=app(),before=a.run('JSON.stringify(B)'),html=a.run('debt()');assert.match(html,/debt-detail-grid/);for(const label of ['Current Balance','Credit Limit','Scheduled Payment','Record Payment','Edit Account','Delete Account'])assert.ok(html.includes(label),label);assert.equal(a.run('JSON.stringify(B)'),before);});
test('safe-to-spend presentation keeps saved-money details and a close action',()=>{const a=app();a.run("explain('safe')");const html=a.nodes('#modal-body').innerHTML;for(const label of ['Current Cash','Money Set Aside','Protected Buffer','Bills','Got It'])assert.ok(html.includes(label),label);assert.match(html,/safe-reserved/);assert.match(html,/data-action="close"/);});
test('Income uses source choices and supports deposit review',()=>{const a=app();a.run("B.transactions=['2026-08-13','2026-08-27','2026-09-10'].map((date,i)=>({id:'pay'+i,accountId:B.accounts[0].id,name:B.incomes[0].historyName||B.incomes[0].name,date,amount:i===0?300:1000,direction:'Inflow',category:'Income',historical:true}));S.analysis=null");a.run('incomeHistory(B.incomes[0].id)');const html=a.nodes('#modal-body').innerHTML;for(const label of ['Typical:','Cautious:','Estimate','Use in estimate','Exclude'])assert.ok(html.includes(label),label);assert.doesNotMatch(a.run('incomePage()'),/Forecast Choices/);assert.doesNotMatch(a.run('plan()'),/Forecast Choices/);assert.match(a.run('incomeSourcesPage()'),/income-plan-amount/);});
test('search finds existing records and escapes their names',()=>{const a=app();assert.match(a.run("budgetSearchResults('internet')"),/data-action="bill"/);assert.match(a.run("budgetSearchResults('card')"),/data-action="account"/);a.run("B.needs=[{id:'n',name:'<img src=x onerror=alert(1)>',cost:10}]");assert.doesNotMatch(a.run("budgetSearchResults('img')"),/<img src=x/);assert.match(a.run("budgetSearchResults('unfindable')"),/Nothing matches/);});
test('Settings uses focused tabs and a simplified recovery layout',()=>{const a=app(),home=a.run('settings()');for(const text of ['Accounts & Connections','Income','Data & Recovery','Privacy & Preferences'])assert.ok(home.includes(text),text);assert.match(home,/role="tablist"/);a.context.location.hash='#settings/data';const html=a.run('settings()');for(const text of ['Export Budget','Backups & Restore','View History & Restore','Backup Now','Recently Deleted','0 items · kept 30 days','System Health','Sign Out'])assert.ok(html.includes(text),text);for(const removed of ['Export Transactions','Export Source Archive','Original import & saved notes'])assert.ok(!html.includes(removed),removed);assert.match(html,/aria-selected="true"[^>]*>Data & Recovery/);assert.match(html,/<details class="section card system-health"/);assert.match(html,/<summary>View Diagnostic Details<\/summary>/);});
test('desktop styles are loaded after shared styles and include scrollable rounded dialogs',()=>{const html=readFileSync(new URL('../index.html',import.meta.url),'utf8'),css=readFileSync(new URL('../desktop-theme.css',import.meta.url),'utf8');assert.ok(html.indexOf('/desktop-theme.css')>html.indexOf('/mobile.css'));assert.match(css,/@media\(min-width:981px\)/);assert.match(css,/\.modal\[open\]\{display:flex;flex-direction:column/);assert.match(css,/#modal-body\{flex:1;max-height:none/);assert.match(html,/modal-symbol/);});
function app(){const elements=new Map(),listeners={},nodes=s=>{if(!elements.has(s))elements.set(s,{dataset:{},innerHTML:'',textContent:'',open:false,show(){this.open=true;},showModal(){this.open=true;},close(){this.open=false;},focus(){},scrollTop:0,addEventListener(){},querySelector(){return null;},querySelectorAll(){return [];},elements:new Proxy({},{get:()=>({addEventListener(){},closest(){return null;},value:'',checked:false})})});return elements.get(s);};const context={debtIconNames,needMatchCandidates,boostAllocation,defaultAllocations,allocationKeys,unmatchedScheduledBills,bankMatchCandidates,bankDebtOccurrences,...financialGoals,...types,categories:types.CATEGORIES,createToolsUI,recentCashActivity,transactionStyle,URLSearchParams,console,URL,Intl,Date,structuredClone,crypto,restoreSections,buildPlan,forecastReconciliation,calculateScenario,...trips,...workflow,...analysis,navigator:{},sessionStorage:{setItem(){}},location:{hash:'#home'},document:{querySelector:nodes,addEventListener:(name,fn)=>listeners[name]=fn,activeElement:{focus(){}}},window:{addEventListener:(name,fn)=>listeners[name]=fn},setTimeout,Blob};vm.createContext(context);vm.runInContext('"use strict";\n'+readFileSync(new URL('../app.js',import.meta.url),'utf8').replace(/^import .*;\n/gm,'').replace(/^export .*;\n/gm,'').replace(/^load\(\)\.catch\(e=>notice\(e.message\)\);$/gm,''),context);const b=fixture();context.data=b;context.sum=summary(b,date);vm.runInContext('B=data;S=sum;',context);return {context,nodes,listeners,run:code=>vm.runInContext(code,context)};}
test('all main screen render functions run against a confirmed local budget',async()=>{const a=app();for(const page of ['home','plan','debt','goals','transactions','settings'])assert.ok(a.run(`${page}()`).length>100,page);a.context.calendarResponse={events:eventsFor(fixture(),date,'2026-09-30'),income:incomeEvents(fixture(),date,'2026-09-30')};a.run('api=async()=>calendarResponse;');const markup=await a.run('calendar()');assert.match(markup,/Internet/);assert.match(markup,/\$60.00/);assert.doesNotMatch(markup,/−\$/);});
test('Calendar month groups recurring bill occurrences by schedule and keeps one-time bills separate',()=>{const a=app();a.run("B.bills=[{id:'monthly',name:'Rent',amount:900,date:'2026-09-01',frequency:'Monthly',category:'Housing',active:true},{id:'once',name:'Dentist',amount:120,date:'2026-09-20',frequency:'One-time',category:'Health',active:true}]");const debtId=a.run('B.accounts[1].id');const occurrences=[{id:'monthly',name:'Rent',date:'2026-09-01',amount:900},{id:'monthly',name:'Rent',date:'2026-09-15',amount:900},{id:'monthly',name:'Rent',date:'2026-09-29',amount:900,status:'Paid'},{id:'once',name:'Dentist',date:'2026-09-20',amount:120},{id:debtId,debtId,name:'Card',date:'2026-09-10',amount:100}];a.context.occurrences=occurrences;const recurring=a.run("calendarMonthBillRows(occurrences,'2026-09-01','2026-09-30','recurring')"),once=a.run("calendarMonthBillRows(occurrences,'2026-09-01','2026-09-30','once')");assert.equal((recurring.match(/calendar-month-bill/g)||[]).length,2);assert.equal((recurring.match(/<strong>Rent<\/strong>/g)||[]).length,1);assert.match(recurring,/3 occurrences/);assert.match(recurring,/Debt payment/);assert.match(recurring,/Card/);assert.match(recurring,/Sep 29, 2026/);assert.equal((once.match(/calendar-month-bill/g)||[]).length,1);assert.match(once,/Dentist/);});
test('Calendar bill rows open schedule actions while Recurring shows actions inline',()=>{const a=app();const bill=a.run('B.bills[0]');const events=[{id:bill.id,name:bill.name,date:a.run('S.asOf'),amount:bill.amount}];a.context.events=events;const calendar=a.run('calendarMonthBillRows(events,S.asOf,S.asOf)');assert.match(calendar,/<details class="unified-item calendar-month-bill"/);assert.match(calendar,/data-action="bill"/);assert.match(calendar,/data-action="remove"/);const recurring=a.run("calendarBillRows('recurring')");assert.match(recurring,/class="recurring-bill-row"/);assert.doesNotMatch(recurring,/<details/);});
test('credit utilization derives from credit limit and falls after a payment',()=>{const a=app();assert.match(a.run('debt()'),/50.0% used/);let b=fixture();b=change(b,'payment',{debtId:b.accounts[1].id,amount:100,principal:100,date},date);a.context.sum=summary(b,date);a.run('S=sum');assert.match(a.run('debt()'),/40.0% used/);});
test('needs offer explicit suggested and custom dates; wishes keep long options collapsed',()=>{const a=app();a.run('needForm()');assert.match(a.nodes('#modal-body').innerHTML,/Suggested Date/);assert.match(a.nodes('#modal-body').innerHTML,/Select a Date/);a.run('goalForm()');assert.match(a.nodes('#modal-body').innerHTML,/<details[^>]*><summary>Link & Photo/);assert.match(a.nodes('#modal-body').innerHTML,/photoFile/);});
