test('unconfirmed finances do not display safe-to-spend as usable money',()=>{const a=app();a.run('S.ready=false');assert.match(a.run('home()'),/Check account balances|Complete your schedules/);a.run("explain('safe')");assert.match(a.nodes('#modal-title').textContent,/Finish Checking/);});
