test('Home pending-account form submits its correction and removes the row',async()=>{const a=app();a.run('B.accounts[0].verified=false');a.context.dispatch=async(path,p)=>{const b=change(a.context.data,p.action,p.data,date);a.context.data=b;return {book:b,summary:summary(b,date),undoId:'saved-change'};};a.run('api=dispatch;reviewAccounts()');assert.match(a.nodes('#modal-body').innerHTML,/1 balance\(s\) left/);a.run('confirmAccount(B.accounts[0].id)');await a.run("saveHandler({balance:'12345'})");assert.equal(a.run('S.cash.balance'),12345);assert.equal(a.run('reviewState(B).balances.length'),0);assert.equal(a.nodes('#modal').open,false);assert.match(a.nodes('#notice').innerHTML,/Account balance confirmed/);});
