test('stylesheet is the uploaded paired v0.1.25 design, with ledger compatibility appended',()=>{const css=readFileSync(new URL('../styles.css',import.meta.url),'utf8');assert.ok(css.startsWith(':root{'));assert.match(css,/--ink:#102843/);assert.match(css,/grid-template-columns:250px 1fr/);assert.match(css,/\.brand-mark/);assert.match(css,/\.month-pill/);assert.match(css,/\.bottom-nav/);const html=readFileSync(new URL('../index.html',import.meta.url),'utf8');assert.match(html,/Personal command center/);assert.match(html,/class="app-shell"/);assert.match(html,/class="page-title"/);});
test('wish confirmation appears only after a successful persisted save',async()=>{const a=app();a.run('readPhoto=async()=>""');a.nodes('#edit-form').elements=new Proxy({},{get:()=>({files:[],value:'',addEventListener(){},closest(){return null;}})});a.context.dispatch=async(path,p)=>{const b=change(a.context.data,p.action,p.data,date);return {book:b,summary:summary(b,date)};};a.run('api=dispatch;goalForm()');await a.run("saveHandler({name:'Camera',cost:200,saved:0,style:'Pause',weekly:0})");assert.equal(a.run('B.wishes[0].name'),'Camera');assert.equal(a.nodes('#modal').open,false);assert.match(a.nodes('#notice').innerHTML,/✓ Wish Saved/);assert.equal(a.nodes('#notice').className,'success-toast');a.run('goalForm();api=async()=>{throw Error("Save failed")}');await assert.rejects(a.run("saveHandler({name:'Not saved',cost:20})"),/Save failed/);assert.equal(a.nodes('#modal-title').textContent,'Wish Details');assert.equal(a.run('B.wishes.length'),1);});
