test('Pause and Unpause stay contextual and never alter saved cash',async()=>{const a=app();a.run("B.wishes=[{id:'wish1',name:'Camera',cost:100,saved:0,style:'Custom',weekly:10}]");a.context.data=a.run('B');a.context.dispatch=async(path,p)=>{const b=change(a.context.data,p.action,p.data,date);a.context.data=b;return {book:b,summary:summary(b,date)};};const before=a.run('S.cash.balance');a.run("api=dispatch;wishCooldown('wish1')");await a.run("saveHandler({pauseUntil:'2026-09-22'})");assert.equal(a.run('S.cash.balance'),before);assert.equal(a.run('B.wishes[0].pauseUntil'),'2026-09-22');let cards=a.run("goalCards('wishes','wish')");assert.match(cards,/data-action="wishResume"/);assert.match(cards,/ Unpause/);assert.match(cards,/wish-waiting/);await a.run("advancedClick('wishResume','wish1','')");cards=a.run("goalCards('wishes','wish')");assert.match(cards,/ Pause/);assert.doesNotMatch(cards,/ Unpause|wish-waiting/);assert.equal(a.run('B.wishes[0].style'),'Custom');assert.equal(a.run('B.wishes[0].weekly'),10);assert.equal(a.run('S.cash.balance'),before);});

test('calendar totals count matched payments once and exclude transfers and corrections',()=>{const a=app();a.run("B.transactions=[{date:'2026-09-15',direction:'Outflow',amount:40},{date:'2026-09-15',direction:'Outflow',amount:100,paymentId:'p'},{date:'2026-09-15',direction:'Outflow',amount:900,toAccountId:'cash2'},{date:'2026-09-15',direction:'Outflow',amount:200,adjustment:true},{date:'2026-10-01',direction:'Outflow',amount:1000}];B.payments=[{id:'p',date:'2026-09-15',amount:100}]");const t=a.run("calendarTotals({events:[],predictedEvents:[{date:'2026-09-15',amount:160},{date:'2026-10-01',amount:900}]},'2026-09-01','2026-09-30')");assert.equal(t.predicted,160);assert.equal(t.actual,140);assert.equal(t.difference,20);});
