test('unified spending matches an existing entry once and rejects an unacknowledged duplicate',()=>{const a=app();let b=fixture();b=change(b,'transaction',{accountId:b.accounts[0].id,name:'Bank payment',amount:100,date,direction:'Outflow'},date);a.context.book=b;a.run('B=book');const data={entryType:'debt',debtId:b.accounts[1].id,accountId:b.accounts[0].id,amount:100,principal:80,date};a.context.entry=data;assert.throws(()=>a.run('spendingPayload(entry)'),/possible matching/);a.context.entry={...data,transactionId:b.transactions[0].id};const result=a.run('spendingPayload(entry)');assert.equal(result.action,'payment');b=change(b,result.action,result.data,date);assert.equal(summary(b,date).cash.balance,9900);assert.equal(summary(b,date).accounts[1].balance,420);assert.equal(b.transactions.length,1);assert.equal(b.payments.length,1);assert.throws(()=>change(b,result.action,result.data,date),/unmatched/);});
test('regular spending and a new debt payment use distinct single ledger writes',()=>{const a=app();const regular=a.run("spendingPayload({entryType:'spending',amount:50})");assert.equal(regular.action,'transaction');a.context.entry={entryType:'debt',debtId:a.context.data.accounts[1].id,accountId:a.context.data.accounts[0].id,amount:100,principal:80,date};const payment=a.run('spendingPayload(entry)');assert.equal(payment.action,'payment');const b=change(a.context.data,payment.action,payment.data,date);assert.equal(b.transactions.length,0);assert.equal(b.payments.length,1);assert.equal(summary(b,date).cash.balance,9900);});
