test('Next Paycheck Plan shows main categories; Next Target previews income and detailed allocations by paycheck',async()=>{const a=app();a.run("B.goals=[{id:'g',name:'Reserve',saved:0,cost:500,style:'Automatic'}];B.wishes=[{id:'w',name:'Headphones',saved:0,cost:400,style:'Automatic'}];B.sinking=[{id:'s',name:'Car Repair',saved:0,cost:300,style:'Automatic'}]");const panel=a.run('paycheckPanel()');for(const name of ['Extra Debt','Sinking Funds','Saving Goals','Wishes','Flexible Spending'])assert.ok(panel.includes('<b>'+name+'</b>'),name);assert.doesNotMatch(panel,/Goals, Wishes and Extra Debt|financial-target-allocation-row|Reserve|Headphones|Car Repair|Extra payment ·/);assert.match(panel,/financial-allocation-category/);a.run('chooseNextTarget()');const target=a.nodes('#modal-body').innerHTML;assert.match(target,/Where the allocations go/);assert.match(target,/id=\"next-target-breakdown\"/);assert.match(target,/expected/);const beforeTarget=a.nodes('#next-target-breakdown').innerHTML;assert.match(beforeTarget,/expected/);assert.match(beforeTarget,/targetPaycheckNext/);assert.match(a.nodes('#modal-symbol').innerHTML,/data-icon="wishTarget"/);assert.match(a.nodes('#modal-symbol').className,/tone-gold/);assert.match(beforeTarget,/data-icon="sinking"/);await a.run("advancedClick('targetPaycheckNext','','')");assert.notEqual(a.nodes('#next-target-breakdown').innerHTML,beforeTarget);const plan=a.run('buildPlan(B,S).periods[0]'),allocation={parts:{debt:10,sinking:10,goals:30,wishes:20},surplus:100,date:plan?.date||'2026-09-29',until:plan?.date||'2026-09-29'};a.context.allocation=allocation;const detail=a.run('financialAllocationDetails(B,S,allocation).markup');for(const name of ['Reserve','Headphones','Car Repair'])assert.ok(detail.includes(name),name);assert.match(detail,/financial-target-allocation-row/);a.run("B.goals=[{id:'milestone',name:'Credit Card to 50%',goalType:'debt',debtId:B.accounts[1].id,startBalance:500,targetBalance:250}];B.settings.priorityTarget={list:'goals',id:'milestone'}");const linked=a.run('financialAllocationDetails(B,S,allocation,{nextTarget:true}).markup');assert.match(linked,/Credit Card to 50% - Additional debt payment/);assert.match(linked,/financial-target-allocation-row[\s\S]*?tone-lav[\s\S]*?data-icon=\"target\"/);assert.match(linked,/<b>Saving Goals<\/b>/);});
test('Goals tiles are compact; gold glow tracks selected target and Sinking Funds is blue',async()=>{const a=app();a.run("B.sinking=[{id:'s',name:'Car Repair',saved:40,cost:400,style:'Automatic'}]");const html=a.run('goals()'),labels=['Wish List Savings','Financial Goal Progress','Sinking Funds','Next Target'];let last=-1;for(const label of labels){const index=html.indexOf(label);assert.ok(index>last,label);last=index;}assert.match(html,/data-action="sinkingSavings"/);const css=readFileSync(new URL('../budget-updates.css',import.meta.url),'utf8');assert.match(css,/reference-goal-top>\.kpi:nth-child\(3\)[\s\S]*?eaf4fc/);assert.match(css,/reference-goal-top>\.kpi>\.icon-badge \{ float:none/);assert.match(css,/reference-goal-top>\.kpi \{ display:flex; align-items:center; gap:10px; min-height:100px; padding:12px; \}/);assert.match(css,/reference-goal\[data-target-card\] \{[^}]*#dfb84a/);assert.match(css,/reference-goal\[data-target-card\]\.is-next-target \{ box-shadow:[^}]*#d7aa3560/);assert.doesNotMatch(html,/Drag a goal or wish to the first position/);await a.run("advancedClick('sinkingSavings','','')");let body=a.nodes('#modal-body').innerHTML;assert.equal(a.nodes('#modal-title').textContent,'Sinking Funds by Paycheck');for(const label of ['Already Set Aside','Projected New Savings','Projected Sinking Funds','Sinking Fund','Contribution','Income'])assert.ok(body.includes(label),label);assert.match(body,/<th><span>Sinking Fund<\/span><br><span>Contribution<\/span><\/th>/);assert.doesNotMatch(body,/<th>Status<\/th>/);assert.match(body,/goal-paycheck-table/);let table=body.match(/<tbody>[\s\S]*?<\/tbody>/)?.[0]||'',rows=[...table.matchAll(/<tr><td>[^<]*<\/td><td>\$([\d,]+\.\d{2})<\/td><td>\$([\d,]+\.\d{2})<\/td>/g)];assert.ok(rows.some(([,income,contribution])=>Number(contribution.replace(',',''))>0));for(const [,income,contribution] of rows)assert.ok(Number(contribution.replace(',',''))<=Number(income.replace(',','')),'sinking fund allocation must fit inside paycheck income');await a.run('wishSavingsForecastDialog()');body=a.nodes('#modal-body').innerHTML;assert.equal(a.nodes('#modal-title').textContent,'Wish List Savings by Paycheck');assert.doesNotMatch(body,/<th>Status<\/th>/);});
test('Financial Goal Progress covers savings and debt milestones while wishes stay separate',async()=>{const a=app();a.run("B.goals=[{id:'save',name:'Emergency Reserve',goalType:'emergency',saved:150,cost:500,months:2,style:'Automatic'},{id:'milestone',name:'Card Payoff',goalType:'debt',debtId:B.accounts[1].id,startBalance:500,targetBalance:100}]");const tile=a.run('goals()');assert.match(tile,/Financial Goal Progress/);assert.match(tile,/1 savings · 1 debt milestones/);await a.run("advancedClick('financialGoalProgress','','')");const body=a.nodes('#modal-body').innerHTML;assert.doesNotMatch(body,/Emergency Reserve|Card Payoff|Current balance|financial-progress-item|<th>Status<\/th>/);assert.match(body,/Wish List Savings remains separate/);for(const label of ['Already Set Aside','Projected New Savings','Projected Goal Savings','Paycheck','Income','Money Allocated to Goals','Projected Total'])assert.ok(body.includes(label),label);assert.match(body,/goal-paycheck-table/);const table=body.match(/<tbody>[\s\S]*?<\/tbody>/)?.[0]||'';assert.doesNotMatch(table,/Status|Card Payoff|Emergency Reserve/);assert.match(table,/\$274\.00/);assert.match(body,/<th>Projected Total<\/th>/);const paycheckAmounts=[...table.matchAll(/<tr><td>[^<]*<\/td><td>\$([\d,]+\.\d{2})<\/td><td>\$([\d,]+\.\d{2})<\/td><td>\$([\d,]+\.\d{2})<\/td>/g)];assert.ok(paycheckAmounts.length>0);let previous=0;for(const [,income,allocated,total] of paycheckAmounts){assert.ok(Number(allocated.replace(',',''))<=Number(income.replace(',','')),'goal allocations must not exceed that paycheck');assert.ok(Number(total.replace(',',''))>=previous,'projected total should accumulate');previous=Number(total.replace(',',''));}});
test('Calendar and monthly review share duplicate treatment and actual totals',()=>{const a=app();a.run("B.transactions=[{id:'one',date:S.asOf,accountId:B.accounts[0].id,name:'Shop',amount:25,direction:'Outflow',category:'Shopping'},{id:'two',date:S.asOf,accountId:B.accounts[0].id,name:'Shop',amount:25,direction:'Outflow',category:'Shopping'}]");const t=a.run("calendarTotals({events:[]},'2026-09-01','2026-09-30')"),r=a.run("monthlyReport(B,S,'2026-09')");assert.equal(t.actual,r.spending+r.payments);assert.equal(t.actual,0);assert.equal(t.withheld,2);a.run("B.dismissedDuplicates=['one|two']");assert.equal(a.run("calendarTotals({events:[]},'2026-09-01','2026-09-30').actual"),50);});
