test('calendar gradients load last and revised readonly dialogs contain no editing controls',()=>{const html=readFileSync(new URL('../index.html',import.meta.url),'utf8'),css=readFileSync(new URL('../refinements.css',import.meta.url),'utf8');assert.ok(html.indexOf('/refinements.css')>html.indexOf('/desktop-theme.css'));for(const n of [1,2,3])assert.ok(css.includes('nth-child('+n+'){background:linear-gradient'));const a=app();a.run("explain('safe')");assert.doesNotMatch(a.nodes('#modal-body').innerHTML,/data-action="goal"/);const pay=a.run('paycheckPanel(true)');assert.doesNotMatch(pay,/Before Your Next Paycheck|data-action="bill"|data-action="account"/);assert.match(pay,/paycheck-allocation-row/);assert.match(pay,/paycheck-bills/);const debt=a.run('debt()');assert.match(debt,/grid debt-top/);assert.doesNotMatch(debt,/data-action="debtAccounts"/);});

function connectLedger(a){a.context.dispatch=async(path,p)=>{const b=change(a.context.data,p.action,p.data,date);a.context.data=b;return {book:b,summary:summary(b,date),undoId:'tools-undo'};};a.run('api=dispatch');}
