test('Insights month selector remains on Insights and Reports heatmap opens and closes inline',async()=>{const a=app();a.context.location.hash='#insights?month=2026-09';await a.run('render()');assert.equal(a.nodes('#title').textContent,'Insights');a.run("B.transactions=[{id:'food',date:S.asOf,accountId:B.accounts[0].id,name:'Food shop',amount:25,direction:'Outflow',category:'Groceries'}]");a.context.location.hash='#reports/annual';await a.run('render()');assert.match(a.nodes('#content').innerHTML,/tools-heatmap/);await a.run(`toolsUI.action('tools-heat',JSON.stringify(['2026','Groceries','2026-09']))`);assert.match(a.nodes('#content').innerHTML,/tools-heat-detail/);assert.match(a.nodes('#content').innerHTML,/Food shop/);await a.run("toolsUI.action('tools-close-heat')");assert.doesNotMatch(a.nodes('#content').innerHTML,/class="tools-heat-detail"/);});
test('Tools category save clears review and preserves cash; deletion reverses exactly that entry',async()=>{const a=app();a.context.data=change(a.context.data,'transaction',{accountId:a.context.data.accounts[0].id,name:'Shop',date,amount:50,direction:'Outflow',category:'Other'},date);a.context.sum=summary(a.context.data,date);a.run('B=data;S=sum');connectLedger(a);a.context.location.hash='#transactions/review';await a.run('render()');await a.run("toolsUI.action('tools-category',B.transactions[0].id)");assert.match(a.nodes('#modal-body').innerHTML,/name="category"/);await a.run("saveHandler({category:'Groceries'})");assert.equal(a.run('B.transactions[0].category'),'Groceries');assert.equal(a.run('S.cash.balance'),9950);assert.match(a.nodes('#content').innerHTML,/All Caught Up/);await a.run("toolsUI.action('tools-delete-transaction',B.transactions[0].id)");assert.equal(a.run('B.transactions.length'),1);await a.run('saveHandler({})');assert.equal(a.run('B.transactions.length'),0);assert.equal(a.run('S.cash.balance'),10000);assert.match(a.nodes('#notice').innerHTML,/UNDO/);});
test('Tools payment match corrects cash once and linked records cannot be deleted independently',async()=>{const a=app();let b=a.context.data;b=change(b,'payment',{debtId:b.accounts[1].id,fundingId:b.accounts[0].id,date,amount:100,principal:80},date);b=change(b,'transaction',{accountId:b.accounts[0].id,date,name:'Bank payment',direction:'Outflow',amount:100},date);a.context.data=b;a.context.sum=summary(b,date);a.run('B=data;S=sum');connectLedger(a);a.context.location.hash='#transactions/review';await a.run('render()');assert.equal(a.run('S.cash.balance'),9800);await a.run("toolsUI.action('tools-match',B.payments[0].id)");a.context.transactionId=b.transactions[0].id;await a.run('saveHandler({transactionId})');assert.equal(a.run('S.cash.balance'),9900);assert.equal(a.run('S.accounts[1].balance'),420);await assert.rejects(a.run("toolsUI.action('tools-match',B.payments[0].id)"),/no longer available/i);a.context.location.hash='#transactions/all';const html=a.run('transactions()');assert.match(html,/tools-view-transaction/);assert.doesNotMatch(html,/tools-delete-transaction/);});
test('Tools imported-record review requires selection and preserves current cash',async()=>{const a=app();a.context.data.reviewTransactions=[{id:'old1',date,accountId:a.context.data.accounts[0].id,name:'Old grocery',amount:30,direction:'Outflow',category:'Groceries'},{id:'old2',date,accountId:a.context.data.accounts[0].id,name:'Old pending',amount:20,direction:'Outflow',category:'Other'}];a.run('B=data');connectLedger(a);a.context.document.querySelectorAll=()=>[];await a.run("toolsUI.action('tools-imports')");assert.match(a.nodes('#modal-body').innerHTML,/form-error/);await assert.rejects(a.run("toolsUI.action('tools-accept-imports')"),/Select at least/);a.context.document.querySelectorAll=()=>[{dataset:{toolsImport:'old1'}}];await a.run("toolsUI.action('tools-accept-imports')");assert.equal(a.run('B.transactions[0].historical'),true);assert.equal(a.run('B.reviewTransactions.length'),1);assert.equal(a.run('S.cash.balance'),10000);a.context.document.querySelectorAll=()=>[{dataset:{toolsImport:'old2'}}];await a.run("toolsUI.action('tools-discard-imports')");assert.equal(a.run('B.reviewTransactions.length'),0);assert.equal(a.run('B.transactions.length'),1);});
test('Tools report source links and search preserve filters and escape names',async()=>{const a=app();a.run("B.transactions=[{id:'food',date:S.asOf,accountId:B.accounts[0].id,name:'<img src=x>',amount:25,direction:'Outflow',category:'Groceries'}]");a.context.location.hash='#transactions/all';assert.doesNotMatch(a.run('transactions()'),/<img src=x>/);await a.run(`toolsUI.action('tools-source',JSON.stringify(['food']))`);assert.match(a.context.location.hash,/ids=food/);a.context.history={replaceState:(_a,_b,hash)=>a.context.location.hash=hash};a.run("toolsUI.search('nothing')");assert.match(a.nodes('#tools-tx-list').innerHTML,/No transactions match/);assert.match(a.context.location.hash,/ids=food/);assert.match(a.context.location.hash,/q=nothing/);});

