test('Accounts and Connections puts account management first and restores the blue Plaid wallet-link disclosure',()=>{const a=app();a.context.location.hash='#settings/accounts';const html=a.run('settings()');assert.ok(html.indexOf('settings-accounts-dropdown')<html.indexOf('settings-plaid-dropdown'));assert.ok(html.indexOf('managed-accounts')<html.indexOf('account-add-bottom'));assert.match(html,/<details class="section card settings-accounts-dropdown"[^>]*open/);assert.match(html,/<details class="section card settings-plaid-dropdown"/);assert.match(html,/data-icon="match"/);assert.match(html,/icon-badge tone-blue/);assert.match(html,/settings-plaid-summary/);assert.match(html,/id="plaid-content"/);assert.match(html,/Manage Accounts/);assert.match(html,/class="secondary account-add-bottom"/);assert.match(html,/data-action="account"/);const css=readFileSync(new URL('../budget-updates.css',import.meta.url),'utf8');assert.match(css,/settings-plaid-dropdown \.plaid-setup-actions[^}]*grid-template-columns:repeat\(2,minmax\(0,1fr\)\); gap:8px/);assert.match(css,/\.reference-ui \.settings-tabs \{ margin-top:4px!important; margin-bottom:6px!important/);assert.match(css,/\.reference-ui \.accounts-connections \{ gap:3px; \}/);assert.match(css,/\.reference-ui \.accounts-connections > \.settings-accounts-dropdown,[\s\S]*?\.settings-plaid-dropdown \{ margin-top:0; \}/);assert.match(css,/\.reference-ui \.account-add-bottom \{ display:block; width:calc\(100% - 12px\); min-height:43px/);});
test('Plaid connection sessions show only the newest Check Connection action at setup-button size',()=>{const a=app();a.run("plaidStatus={configured:true,sample:false,sessions:[{id:'one',url:'https://example.test/one'},{id:'two',url:'https://example.test/two'},{id:'three',url:'https://example.test/three'}],items:[],accountSync:{notes:[]}};");const html=a.run('plaidConnectionsMarkup()');assert.doesNotMatch(html,/Complete sign-in with Plaid, then check the connection here|Open Plaid Sign-In|example\.test/);assert.equal((html.match(/Check Connection/g)||[]).length,1);assert.match(html,/data-id="three"/);const css=readFileSync(new URL('../budget-updates.css',import.meta.url),'utf8');assert.match(css,/\.settings-plaid-dropdown \.plaid-session \.actions \{ display:grid; grid-template-columns:repeat\(2,minmax\(0,1fr\)\); gap:8px; \}/);assert.match(css,/\.plaid-session \.actions > button \{ min-width:0; min-height:43px; border:1px solid var\(--line\); border-radius:10px; padding:10px 12px/);});
