test('Plaid colors follow successful checks and never label an error or unconnected bank as connected',()=>{const a=app(),now=Date.parse('2026-09-16T12:00:00Z');a.context.bankNow=now;for(const [item,label,tone] of [[{checkedAt:'2026-09-16T11:00:00Z'},'Connected','connected'],[{checkedAt:'2026-09-15T12:00:00Z'},'Stale','stale'],[{checkedAt:'2026-09-09T12:00:00Z'},'Old','old'],[{checkedAt:'2026-09-16T11:00:00Z',error:'NO_ACCOUNTS'},'Connection Issue','issue'],[{},'Not Checked','stale']]){a.context.bankItem=item;const state=a.run('plaidConnectionState(bankItem,bankNow)');assert.equal(state.label,label);assert.equal(state.tone,tone);}a.run('plaidStatus={items:[]}');assert.match(a.run('plaidStatusBadge()'),/Not Connected/);assert.match(a.run('plaidStatusBadge()'),/data-icon="warning"/);a.run('plaidStatus={items:[{checkedAt:new Date().toISOString()}]}');assert.match(a.run('plaidStatusBadge()'),/data-icon="check"/);assert.match(a.run('plaidTileNote()'),/Balances & transactions enabled/);});

