test('Paid past calendar expense stays visible as read-only in the selected day',async()=>{
 const a=app();let b=a.context.data;const key=b.bills[0].id+'@'+date;b=change(b,'occurrence',{key,date,status:'Paid',accountId:b.accounts[0].id},date);
 a.context.data=b;a.context.sum=summary(b,date);a.context.calendarData=calendarView(b,'2026-08-30','2026-10-03',date,a.context.sum);a.run("B=data;S=sum;S.asOf='2026-09-16';selectedDay='2026-09-15';api=async()=>calendarData");
 await a.run('calendarMonthView()');const html=a.run('dayDetails()');assert.match(html,/Internet/);assert.match(html,/Internet[\s\S]*?Recorded · manage from Transactions or Debt/);const record=html.slice(html.indexOf('<strong>Internet</strong>'),html.indexOf('</div></div>',html.indexOf('<strong>Internet</strong>')));assert.doesNotMatch(record,/data-action="(?:bill|skip|remove)"/);
});
test('global Forecast Choices is absent from Income and Plan',()=>{const a=app();assert.doesNotMatch(a.run('incomePage()'),/Forecast Choices/);assert.doesNotMatch(a.run('plan()'),/Forecast Choices/);});

test('dismissed recurring suggestions are in the Recurring tab with restore controls',()=>{const a=app();a.context.recurringBillSuggestions=()=>[{key:'dismissed',dismissed:true,name:'Old subscription',accountName:'Checking',frequency:'Monthly',evidence:[{date:'2026-09-01'}],amount:12}];const recurring=a.run('recurring()');assert.match(recurring,/Dismissed Recurring Charges/);assert.match(recurring,/data-action="recurringReview"/);a.context.location.hash='#settings/data';const data=a.run('settings()');assert.doesNotMatch(data,/Dismissed Recurring Charges/);});

test('removing the source archive keeps migration notes in Transactions review',()=>{const a=app();a.run("B.migration.unresolved=['Check an imported account'];");assert.match(a.run('transactions()'),/Saved import notes/);assert.match(a.run('transactions()'),/Check an imported account/);a.context.location.hash='#settings/data';const html=a.run('settings()');assert.doesNotMatch(html,/Saved import notes|Check an imported account/);});
